import{_ as o,a0 as s,w as r,s as p,ao as u,I as l,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"怎樣使用linux的iptables工具進行網絡共享 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣使用linux的iptables工具進行網絡共享 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣使用linux的iptables工具進行網絡共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣使用linux的iptables工具進行網絡共享 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140610 How to set up Internet connection sharing with iptables on Linux","title":"怎樣使用linux的iptables工具進行網絡共享","tag":"201406","desc":""},"relativePath":"201406/20140610 How to set up Internet connection sharing with iptables on Linux.md","filePath":"[post].md"}'),d={name:"201406/20140610 How to set up Internet connection sharing with iptables on Linux.md"};function h(x,e,c,b,T,P){const n=s("Link");return r(),p("div",null,[e[11]||(e[11]=u(`<h1 id="怎樣使用linux的iptables工具進行網絡共享" tabindex="-1">怎樣使用linux的iptables工具進行網絡共享 <a class="header-anchor" href="#怎樣使用linux的iptables工具進行網絡共享" aria-label="Permalink to “怎樣使用linux的iptables工具進行網絡共享”">​</a></h1><p>在本教程中，我將解釋多個設備怎樣在linux下共享一個網絡連接。目前無線路由器已經成為主流的消費品，從而解決了本文這一問題。這裏假設你家中並沒有一台無線路由器，不過，你卻有一台已經有&quot;貓&quot;和有線網卡的的linux主機。&quot;貓&quot;是以動態公有IP地址的模式連接到互聯網，主機的網卡連接到你的交換機或者集線器。其他設備（如linux或者windows的PC或者筆記本）以網橋的形式連接，並且沒有連接到互聯網。為了共享linux主機的互聯網，你必須把主機轉換成網關，以便它能實現從其他設備中傳送和接受信息。</p><h3 id="術語字彙" tabindex="-1">術語字彙 <a class="header-anchor" href="#術語字彙" aria-label="Permalink to “術語字彙”">​</a></h3><ul><li><strong>私有IP地址</strong>（路由不可達地址）是一個被用於本地局域網的IP地址（在互聯網中不可見）。</li><li><strong>公用IP地址</strong>（路由可達地址）是一個在互聯網中可見的IP地址。</li><li><strong>IP偽裝</strong>是一項允許一系列機器通過MASQ網關連接互聯網的功能。這些MASQ網關之外的機器在互聯網中是不可見的。MASQ之後的機器中任何流入或流出的數據必須經過MASQ網關。</li><li><strong>網絡地址轉換</strong>（NAT）是一項通過IP偽裝技術可以使私有IP地址訪問互聯網的功能。</li></ul><h3 id="hardware-requirements" tabindex="-1">Hardware Requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to “Hardware Requirements”">​</a></h3><p>硬件要求</p><ul><li>一台有兩個接口（一個公有IP地址和其他的私有IP地址）的linux主機，這個主機將被用作網關。</li><li>一台或者多台擁有私有IP地址的linux/windows系統的PC或者筆記本。</li><li>交換機/集線器（可選）。</li></ul><h3 id="教程步驟" tabindex="-1">教程步驟 <a class="header-anchor" href="#教程步驟" aria-label="Permalink to “教程步驟”">​</a></h3><p>接下來的過程需要在linux主機（用於共享的網關）上完成。</p><h4 id="_1、激活ip轉發" tabindex="-1">1、激活IP轉發 <a class="header-anchor" href="#_1、激活ip轉發" aria-label="Permalink to “1、激活IP轉發”">​</a></h4><p>為了設置網絡共享，你需要在linux主機上更改一個內核參數來使能IP轉發功能。內核啓動參數設定在/etc/sysctl.conf文件中。</p><p>打開這個文件，定位到含有&quot;# net.ipv4.ip_forward = 0&quot;的這一行，移除#號（即取消註釋），然後將其值設置為1，改好之後應該和下面的一致。</p><pre><code>net.ipv4.ip_forward = 1
</code></pre><p>你還要使激活IP轉發功能生效，通過執行下面的命令：</p><pre><code>$ sudo sysctl -w net.ipv4.ip_forward=1
$ sudo sysctl -p
</code></pre><h4 id="_2、nat配置" tabindex="-1">2、NAT配置 <a class="header-anchor" href="#_2、nat配置" aria-label="Permalink to “2、NAT配置”">​</a></h4><p>另一個網絡共享的重要部分是NAT配置，這可以通過使用iptables的命令，iptables包含四個防火牆的規則表：</p><ul><li>FILTER (默認表格)</li><li>NAT</li><li>MANGLE</li><li>RAW</li></ul><p>這個教程中我們將僅使用兩個表格：FILTER和NAT表格。</p><p>首先，刷新所有活躍的防火牆的規則。</p><pre><code>$ sudo iptables -X
$ sudo iptables -F
$ sudo iptables -t nat -X
$ sudo iptables -t nat -F
</code></pre><p>在輸入表格中，你需要設置轉發鏈（FORWARD）成可接受的（ACCEPT）目的地，因此所有通過主機的數據包將會被正確的處理。</p><pre><code>$ sudo iptables -I INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT
$ sudo iptables -I FORWARD -m state --state RELATED,ESTABLISHED -j ACCEPT
</code></pre><p>在NAT表中，你必須為你的WAN口啓用IP偽裝功能，我們假設WAN口協議是ppp0。為了在ppp0接口上使能IP偽造技術，我們使用以下的命令：</p><pre><code>$ sudo iptables -t nat -I POSTROUTING -o ppp0 -j MASQUERADE
</code></pre><h4 id="_3、配置私有ip地址" tabindex="-1">3、配置私有IP地址 <a class="header-anchor" href="#_3、配置私有ip地址" aria-label="Permalink to “3、配置私有IP地址”">​</a></h4><p>在linux主機上的所有配置完成後，你需要配置其他設備（linux/windows的PC或筆記本）的DNS服務器以及默認網關，讓它們的數據流可以指向linux主機。注意你不需要在linux主機上設置一個DNS服務器，從其他設備發出的每一個DNS請求都會通過上游的ISP自動轉發到linux主機上。</p><p>如果你的其他設備上用的系統是linux，你可以通過以下命令來更改他們的默認網關和DNS服務器。假設你的網段是192.168.1.0/24的私有IP地址網段，linux主機上綁定的IP地址是192.168.1.1。</p><pre><code>$ sudo ip route del default
$ sudo ip route add default via 192.168.1.1
$ sudo sh -c &quot;echo &#39;nameserver 192.168.1.1&#39; &gt; /etc/resolv.conf&quot;
</code></pre><p>如果還有其他的linux設備，那麼你可以重複以上命令。</p><p>如果你有windows設備，你可以通過控制面板的網絡連接屬性來更改默認網關和DNS服務器。</p><h4 id="_4、完整的腳本" tabindex="-1">4、完整的腳本 <a class="header-anchor" href="#_4、完整的腳本" aria-label="Permalink to “4、完整的腳本”">​</a></h4><p>這是一個在linux主機上設置網絡連接共享的一個完整的腳本。WAN口（ppp0協議）需要根據你具體的網絡接口協議來替換。</p><pre><code>$ sudo vi /usr/local/bin/ishare
</code></pre><hr><pre><code>#!/bin/bash

## Internet connection shating script

sysctl -w net.ipv4.ip_forward=1
sysctl -p
iptables -X
iptables -F
iptables -t nat -X
iptables -t nat -F
iptables -I INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT
iptables -I FORWARD  -m state --state RELATED,ESTABLISHED -j ACCEPT
iptables -t nat -I POSTROUTING -o ppp0 -j MASQUERADE
</code></pre><p>保存以上的腳本到/usr/local/bin/ishare，然後添加可執行權限通過執行下面的命令。</p><pre><code>$ sudo chmox +x /usr/local/bin/ishare
</code></pre><p>如果你需要這個腳本開機啓動，你需要在/etc/rc.local文件中執行這個腳本，並在該文件中的&quot;exit 0&quot;之前添加下面一行。</p><pre><code>/usr/local/bin/ishare
</code></pre><hr>`,41)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),i(n,{href:"http://xmodulo.com/2014/06/internet-connection-sharing-iptables-linux.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://xmodulo.com/2014/06/internet-connection-sharing-iptables-linux.html",-1)])]),_:1})]),l("p",null,[e[4]||(e[4]=t("譯者：",-1)),i(n,{href:"https://github.com/yujianxuechuan"},{default:a(()=>[...e[2]||(e[2]=[t("yujianxuechuan",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[8]||(e[8]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const f=o(d,[["render",h]]);export{A as __pageData,f as default};
